// goKEVulnDBClient is a DB Driver
type goKEVulnDBClient struct {
	driver  kevulndb.DB
	baseURL string
}

// closeDB close a DB connection
func (client goKEVulnDBClient) closeDB() error {
	if client.driver == nil {
		return nil
	}
	return client.driver.CloseDB()
}

func newGoKEVulnDBClient(cnf config.VulnDictInterface, o logging.LogOpts) (*goKEVulnDBClient, error) {
	if err := kevulnlog.SetLogger(o.LogToFile, o.LogDir, o.Debug, o.LogJSON); err != nil {
		return nil, xerrors.Errorf("Failed to set go-kev logger. err: %w", err)
	}

	db, err := newKEVulnDB(cnf)
	if err != nil {
		return nil, xerrors.Errorf("Failed to newKEVulnDB. err: %w", err)
	}
	return &goKEVulnDBClient{driver: db, baseURL: cnf.GetURL()}, nil
}

// FillWithKEVuln :
func FillWithKEVuln(r *models.ScanResult, cnf config.KEVulnConf, logOpts logging.LogOpts) error {
	client, err := newGoKEVulnDBClient(&cnf, logOpts)
	if err != nil {
		return err
	}
	defer func() {
		if err := client.closeDB(); err != nil {
			logging.Log.Errorf("Failed to close DB. err: %+v", err)
		}
	}()

	nKEV := 0
	if client.driver == nil {
		var cveIDs []string
		for cveID := range r.ScannedCves {
			cveIDs = append(cveIDs, cveID)
		}
		prefix, err := util.URLPathJoin(client.baseURL, "cves")
		if err != nil {
			return err
		}
		responses, err := getKEVulnsViaHTTP(cveIDs, prefix)
		if err != nil {
			return err
		}
		for _, res := range responses {
			var kevulns kevulndb.Response
			if err := json.Unmarshal([]byte(res.json), &kevulns); err != nil {
				return err
			}
			v, ok := r.ScannedCves[res.request.cveID]
			if ok {
				v.KEVs = kevEntries(kevulns)
				if len(v.KEVs) > 0 {
					nKEV++
				}
				r.ScannedCves[res.request.cveID] = v
			}
		}
	} else {
		for cveID, vuln := range r.ScannedCves {
			if cveID == "" {
				continue
			}
			kevulns, err := client.driver.GetKEVByCveID(cveID)
			if err != nil {
				return err
			}
			vuln.KEVs = kevEntries(kevulns)
			if len(vuln.KEVs) > 0 {
				nKEV++
			}
			r.ScannedCves[cveID] = vuln
		}
	}

	logging.Log.Infof("%s: Known Exploited Vulnerabilities are detected for %d CVEs", r.FormatServerName(), nKEV)
	return nil
}

// kevEntries maps the two catalog formats to the public vulnerability model.
func kevEntries(response kevulndb.Response) []models.KEV {
	var entries []models.KEV
	for _, cisa := range response.CISA {
		entries = append(entries, models.KEV{
			Type: models.CISAKEVType, VendorProject: cisa.VendorProject,
			Product: cisa.Product, VulnerabilityName: cisa.VulnerabilityName,
			ShortDescription: cisa.ShortDescription, RequiredAction: cisa.RequiredAction,
			KnownRansomwareCampaignUse: cisa.KnownRansomwareCampaignUse,
			DateAdded:                  cisa.DateAdded, DueDate: validKEVDueDate(&cisa.DueDate),
			CISA: &models.CISAKEV{Note: cisa.Notes},
		})
	}
	for _, vc := range response.VulnCheck {
		details := &models.VulnCheckKEV{}
		for _, xdb := range vc.VulnCheckXDB {
			details.XDB = append(details.XDB, models.VulnCheckXDB{
				XDBID: xdb.XDBID, XDBURL: xdb.XDBURL, DateAdded: xdb.DateAdded,
				ExploitType: xdb.ExploitType, CloneSSHURL: xdb.CloneSSHURL,
			})
		}
		for _, report := range vc.VulnCheckReportedExploitation {
			details.ReportedExploitation = append(details.ReportedExploitation, models.VulnCheckReportedExploitation{
				URL: report.URL, DateAdded: report.DateAdded,
			})
		}
		entries = append(entries, models.KEV{
			Type: models.VulnCheckKEVType, VendorProject: vc.VendorProject,
			Product: vc.Product, VulnerabilityName: vc.Name,
			ShortDescription: vc.Description, RequiredAction: vc.RequiredAction,
			KnownRansomwareCampaignUse: vc.KnownRansomwareCampaignUse,
			DateAdded:                  vc.DateAdded, DueDate: validKEVDueDate(vc.DueDate),
			VulnCheck: details,
		})
	}
	return entries
}

func validKEVDueDate(dueDate *time.Time) *time.Time {
	if dueDate == nil || dueDate.IsZero() || dueDate.Year() <= 1 {
		return nil
	}
	return dueDate
}

